    const hatch = cbox(0.22, 0.03, 0.22, 0.008, M.glowSoft);
    hatch.position.set(0, Y + 0.2, -0.14);
    b.add(hatch);
    const r = reactor(0.08, 2.2);
    r.g.position.set(0, Y + 0.08, -0.14);
    b.add(r.g);
    const rt = rotor(0.26);
    rt.g.position.y = Y + 0.38;
    b.add(rt.g);
    const mast = cyl(0.04, 0.06, 0.14, M.gun);
    mast.position.y = Y + 0.26;
    b.add(mast);
    const gun = G();
    gun.position.set(0, Y - 0.2, 0.32);
    b.add(gun);
    const barrels = G();
    gun.add(barrels);
    for (let i = 0; i < 6; i++) {
        const a = i * TAU / 6, br = cyl(0.04, 0.04, 0.75, M.gun, 10);
        br.rotation.x = PI / 2;
        br.position.set(Math.cos(a) * 0.1, Math.sin(a) * 0.1, 0.38);
        barrels.add(br);
    }
    for (const z of [0.12, 0.6]) {
        const cl = torus(0.15, 0.03, M.steel, 24);
        cl.position.z = z;
        barrels.add(cl);
    }
    const mz = torus(0.15, 0.015, M.glow, 24);
    mz.position.z = 0.76;
    barrels.add(mz);
    const flash = glowSprite(0.6);
    flash.position.z = 0.85;
    gun.add(flash);
    const drum = cyl(0.18, 0.18, 0.16, M.dark, 20);
    drum.rotation.z = PI / 2;
    drum.position.set(0.33, Y - 0.08, 0.05);
    b.add(drum);
    const db = torus(0.18, 0.015, M.glow, 24);
    db.rotation.y = PI / 2;
    db.position.set(0.42, Y - 0.08, 0.05);
