;
/* design/evolutions/forms2.js */
M.crystal.emissiveIntensity = 0.32;
M.crystal.roughness = 0.25;
M.crystal.metalness = 0.05;
M.sprite.opacity = 0.4;
const _edgeMat = new T.LineBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.55 });
function hexCrystal(r, h, tip, mat) {
    const g = G();
    mat = mat || M.crystal;
    const edges = mat === M.crystal;
    const part = (geo, y, rx) => {
        const m = new T.Mesh(geo, mat);
        m.position.y = y;
        if (rx)
            m.rotation.x = rx;
        g.add(m);
        if (edges) {
            const e = new T.LineSegments(new T.EdgesGeometry(geo), _edgeMat);
            e.position.y = y;
            if (rx)
                e.rotation.x = rx;
            g.add(e);
        }
    };
    part(new T.CylinderGeometry(r, r, h, 6, 1), 0);
    part(new T.ConeGeometry(r, tip, 6), h / 2 + tip / 2);
    part(new T.ConeGeometry(r, tip * 0.7, 6), -h / 2 - tip * 0.35, PI);
    return g;
}
function crystalCore(r, h, tip, lamp) {
    const g = G();
    g.add(hexCrystal(r, h, tip, M.crystal));
    g.add(hexCrystal(r * 0.45, h * 0.9, tip * 0.6, M.glow));
    g.add(glowSprite((r + h * 0.5) * 2.4));
    const L = new T.PointLight(0xffffff, lamp == null ? 0.5 : lamp * 0.25, 4.5, 2);
    L.position.set(0, 0, 0.9);
    L.color.set(EL.color);
    g.add(L);
    LIGHTS.push(L);
    return g;
}
function sheet(w, h, mat, edge) {
    const g = G();
    g.add(cbox(w, h, 0.03, 0.009, mat || M.armor));
    if (edge !== false) {
        const e = cbox(w * 0.94, 0.014, 0.036, 0.003, M.glow);
        e.position.y = h / 2 - 0.004;
        g.add(e);
    }
    return g;
}
function feather(len, w, mat) {
    const g = G();
    g.add(plate([[0, w * 0.7], [len * 0.82, w], [len, 0], [len * 0.82, -w], [0, -w * 0.7]], 0.03, 0.006, mat || M.armor));
    const e = cbox(len * 0.8, 0.012, 0.034, 0.002, M.glow);
    e.position.set(len * 0.45, w * 0.9, 0);
    g.add(e);
    return g;
}
function hexPlate(R, t, mat) { return new T.Mesh(new T.CylinderGeometry(R, R, t || 0.04, 6), mat || M.armor); }
function hexRing(R, tube, mat) { const m = new T.Mesh(new T.TorusGeometry(R, tube, 4, 6), mat || M.steel); m.rotation.x = PI / 2; return m; }
function scaleOn(parent, p, w, h, tilt, mat) {
    const s = sheet(w, h, mat, false);
    const holder = G();
    holder.position.copy(p);
    holder.lookAt(p.clone().multiplyScalar(2));
    holder.add(s);
    s.rotation.x = -tilt;
    s.position.y = h * 0.1;
    parent.add(holder);
    return holder;
}
