/* design/evolutions/forms3.js */
function thr(r) {
    const g = G();
    g.add(cyl(r, r * 1.2, r * 1.3, M.dark, 14));
    const d = mesh(new T.CircleGeometry(r * 1.0, 16), M.glow, 0, -r * 0.66, 0);
    d.rotation.x = PI / 2;
    g.add(d);
    g.add(mesh(new T.CylinderGeometry(r * 0.9, r * 1.7, r * 3, 16, 1, true), M.wash, 0, -r * 2.2, 0));
    return g;
}
function eye(r, h, lamp) {
    const g = G();
    g.add(hexCrystal(r, h, r * 1.1, M.crystal));
    g.add(glowSprite(r * 7));
    const L = new T.PointLight(0xffffff, lamp == null ? 0.35 : lamp, 3, 2);
    L.position.z = 0.5;
    L.color.set(EL.color);
    g.add(L);
    LIGHTS.push(L);
    return g;
}
function frame(R) { return new T.Mesh(new T.TorusGeometry(R, 0.03, 4, 6), M.steel); }
function visor(w, mat) { return cbox(w, 0.045, 0.04, 0.008, mat || M.glow); }
function arm(parent, a, k, h, r, mat) {
    const u = limb(r, mat || M.armor), l = limb(r * 0.85, M.gun);
    setLink(u, a, k);
    setLink(l, k, h);
    parent.add(u, l);
    for (const p of [a, k, h]) {
        const j = sphere(r * 1.25, M.steel, 10);
        j.position.copy(p);
        parent.add(j);
    }
}
function leg3(parent, hip, knee, foot, r) { arm(parent, hip, knee, foot, r, M.armor); const f = cyl(r * 1.8, r * 2.2, 0.05, M.dark, 8); f.position.copy(foot); parent.add(f); }
function fx(no, desc, build) { f2(no, desc, build); }
