fx(57, "Gimbal warden: a dark sphere with the crystal as a forward eye, three gimbal rings round it, and four curved armour shells floating off it.", () => {
    const g = G(), b = G();
    g.add(b);
    const Y = 1.5, rings = [];
    const ball = sphere(0.34, M.dark, 28);
    ball.position.y = Y;
    b.add(ball);
    const eq = torus(0.345, 0.02, M.steel, 36);
    eq.position.y = Y;
    b.add(eq);
    const e = eye(0.1, 0.3, 0.6);
    e.rotation.x = PI / 2;
    e.position.set(0, Y, 0.34);
    b.add(e);
    const fr = frame(0.16);
    fr.position.set(0, Y, 0.36);
    b.add(fr);
    [[0, 0.52], [PI / 2, 0.58], [PI / 4, 0.64]].forEach(([tilt, R], k) => { const r = torus(R, 0.035, k % 2 ? M.gun : M.armor, 48); r.position.y = Y; r.rotation.set(tilt + (k ? 0 : PI / 2), k * 0.6, 0); b.add(r); rings.push(r); });
    const mat = M.armor.clone();
    mat.side = T.DoubleSide;
    const shells = [];
    for (let i = 0; i < 4; i++) {
        const a = i * PI / 2 + PI / 4, m = mesh(new T.SphereGeometry(0.82, 12, 8, a - 0.5, 1.0, 1.0, 1.1), mat);
        m.position.y = Y;
        b.add(m);
        const ed = mesh(new T.SphereGeometry(0.822, 12, 1, a - 0.5, 1.0, 1.0, 0.025), M.glow);
        ed.position.y = Y;
        b.add(ed);
        shells.push({ m, ed, dir: V(-Math.cos(a) * Math.sin(1.55), Math.cos(1.55), Math.sin(a) * Math.sin(1.55)) });
    }
    for (let i = 0; i < 3; i++) {
        const a = i * TAU / 3, t = thr(0.07);
        t.position.set(Math.sin(a) * 0.22, Y - 0.38, Math.cos(a) * 0.22);
        b.add(t);
    }
    return { g, core: Y, update(t, act) {
            const burst = act > 0.6 ? Math.sin(Math.min(1, (act - 0.6) / 0.4) * PI) : 0;
            rings.forEach((r, i) => r.rotation.z = t * 1.6 * (i === 2 ? 2 : 1) + burst * 0.8);
            shells.forEach(S => { const p = V(0, Y, 0).addScaledVector(S.dir, burst * 0.24); S.m.position.copy(p); S.ed.position.copy(p); });
            b.position.y = bob(t, 2, 0.04);
        } };
});
