function slurryMound(r, h, seed) {
    const geo = new T.SphereGeometry(r, 14, 6, 0, TAU, 0, PI / 2), p = geo.attributes.position;
    for (let i = 0; i < p.count; i++) {
        const x = p.getX(i), y = p.getY(i), z = p.getZ(i), n = _hz(Math.round(x * 300) + seed, Math.round(y * 300), Math.round(z * 300));
        p.setXYZ(i, x * (0.92 + 0.16 * n), y * h / r * (0.8 + 0.4 * n), z * (0.92 + 0.16 * n));
    }
    geo.computeVertexNormals();
    return new T.Mesh(geo, M.slurry);
}
