function _eatenDesign(opts) {
    const g = G(), b = G();
    g.add(b);
    const R = opts.R || 1.0, pool = slurryPool(R, opts.seed, 1);
    b.add(pool);
    const piv = G();
    piv.position.set(0, 0.08, 0);
    piv.rotation.set(opts.tx, 0, opts.tz);
    b.add(piv);
    const cr = eatenCrystal(0.34, opts.h, 0.55, opts.reach);
    cr.position.y = opts.h / 2 + opts.up;
    piv.add(cr);
    const cg = glowSprite(0.85);
    cg.position.y = opts.h * 0.7 + opts.up;
    piv.add(cg);
    const sh = shellShard(0.8, 0.32, 0.05);
    sh.position.set(-0.05, opts.h * 0.8 + opts.up, 0.28);
    sh.rotation.set(0.5, 0.25, 0.3);
    piv.add(sh);
    const mound = slurryMound(0.55, 0.32, opts.seed * 10);
    mound.position.y = 0.0;
    piv.add(mound);
    const bits = [];
    for (let i = 0; i < (opts.bits || 0); i++) {
        const c = eatenCrystal(0.07 + 0.02 * i, 0.18, 0.1, 0.6);
        b.add(c);
        bits.push(c);
    }
    const sp = opts.split ? G() : null;
    if (sp) {
        sp.visible = false;
        b.add(sp);
        const a1 = shellShard(1.3, 0.52, 0.09), a2 = shellShard(1.1, 0.44, 0.09);
        a2.rotation.y = PI / 2;
        sp.add(a1);
        sp.add(a2);
    }
    const blob = opts.spit ? new T.Mesh(new T.SphereGeometry(1, 14, 10), new T.MeshBasicMaterial({ color: new T.Color(0x9adeae).convertSRGBToLinear(), toneMapped: false })) : null, blobSp = [];
    if (blob) {
        blob.visible = false;
        blob.position.set(0, opts.h * 0.97 + opts.up + 0.2, 0.1);
        piv.add(blob);
        const sm = new T.MeshBasicMaterial({ color: new T.Color(0xa9c4b3).convertSRGBToLinear(), toneMapped: false });
        for (let i = 0; i < 6; i++) {
            const sk = new T.Mesh(new T.OctahedronGeometry(1, 0), sm);
            sk.visible = false;
            piv.add(sk);
            blobSp.push(sk);
        }
    }
    const L = new T.PointLight(0xffffff, 0.15, 3.5, 2);
    L.color.set(EL.color);
    L.position.set(0, 1.7, 0.7);
    b.add(L);
    LIGHTS.push(L);
    return { g, core: opts.h * 0.7 + 0.2, update(t, act, v) {
            pool.shift(t);
            const SV = sp && v && v.split != null ? v : null, gr = SV ? SV.split : 0, go = SV && SV.go ? SV.go : 0;
            piv.rotation.z = opts.tz + 0.02 * Math.sin(1.6 * t);
            piv.rotation.x = opts.tx - 0.22 * (act || 0);
            mound.scale.setScalar(1 + 0.04 * Math.sin(1.6 * t + 1) + 0.12 * (act || 0));
            bits.forEach((c, i) => { const a = i * 2.4 + 0.6 + 0.4 * Math.sin(1.6 * t + i), d = (0.7 + 0.15 * i) * R; c.position.set(Math.sin(a) * d, 0.1, Math.cos(a) * d); c.rotation.set(1.1 + i * 0.3, a, 0.5); });
            if (sp) {
                sp.visible = gr > 0.02;
                if (sp.visible) {
                    sp.scale.set(0.45 + 0.55 * gr, gr, 0.45 + 0.55 * gr);
                    sp.position.set(0.78 + 0.5 * go, 0.06 + 1.5 * go * (1 - 0.6 * go), 0.12 + 1.1 * go);
                    sp.rotation.set(0.5 * go, 0.8 * go, 0.4 * go);
                }
                if (SV) {
                    piv.rotation.x -= 0.12 * gr;
                    mound.scale.setScalar(mound.scale.x + 0.25 * gr);
                }
            }
            if (blob) {
                const ST = v && v.blob != null ? v : null, tp = ST ? ST.tip : 0, bg = ST ? ST.blob : 0;
                blob.visible = bg > 0.02;
                if (!blob.visible)
                    blobSp.forEach(sk => { sk.visible = false; });
                if (ST) {
                    piv.rotation.x += 0.35 * tp;
                    mound.scale.setScalar(mound.scale.x + 0.2 * Math.max(0, bg));
                }
                if (blob.visible) {
                    const rr = 0.05 + 0.3 * bg;
                    blob.scale.set(rr, rr * 0.92, rr);
                    blobSp.forEach((sk, i) => { sk.visible = bg > 0.35; if (sk.visible) {
                        const an = i * 1.05 + bg * 3, d = rr * 1.5 + 0.05;
                        sk.position.set(blob.position.x + Math.cos(an) * d, blob.position.y + Math.sin(an) * d * 0.9, blob.position.z + Math.sin(an * 1.7) * 0.08);
                        sk.scale.set(0.012, 0.05 * bg, 0.012);
                        sk.rotation.z = an + PI / 2;
                    } });
                }
            }
        } };
}
