/* design/evolutions/forms6.js */
function warpTex() {
    const c = document.createElement("canvas");
    c.width = c.height = 512;
    const g = c.getContext("2d");
    g.fillStyle = "#000";
    g.fillRect(0, 0, 512, 512);
    g.strokeStyle = "#fff";
    g.lineWidth = 3;
    for (let i = 0; i < 16; i++) {
        const x = (i + 0.5) * 32;
        g.beginPath();
        g.moveTo(x, 0);
        g.lineTo(x, 512);
        g.stroke();
    }
    for (let j = 0; j < 10; j++) {
        const y = j * 512 / 10 + 8;
        g.beginPath();
        g.moveTo(0, y);
        g.lineTo(512, y);
        g.stroke();
    }
    g.lineWidth = 7;
    g.beginPath();
    g.moveTo(0, 505);
    g.lineTo(512, 505);
    g.stroke();
    const t = new T.CanvasTexture(c);
    t.anisotropy = 4;
    return t;
}
