/* design/evolutions/forms7.js */
function kitePlate(w, h, d, mat) { return plate([[-w / 2, h / 2], [w / 2, h / 2], [w / 2, h * 0.05], [0, -h / 2], [-w / 2, h * 0.05]], d, 0.012, mat || M.armor); }
function hexShield(R, d, mat) { const pts = []; for (let i = 0; i < 6; i++) {
    const a = PI / 6 + i * PI / 3;
    pts.push([Math.cos(a) * R, Math.sin(a) * R]);
} return plate(pts, d, 0.012, mat || M.armor); }
function hexTrim(R, mat) { const t = new T.Mesh(new T.TorusGeometry(R, 0.012, 4, 6), mat || M.glow); t.rotation.z = PI / 6; return t; }
function barrel(len, r) {
    const g = G(), t = cyl(r, r * 1.2, len, M.gun, 12);
    t.rotation.x = PI / 2;
    t.position.z = len / 2;
    g.add(t);
    const mz = cyl(r * 1.6, r * 1.6, 0.1, M.dark, 12);
    mz.rotation.x = PI / 2;
    mz.position.z = len;
    g.add(mz);
    const ring = new T.Mesh(new T.TorusGeometry(r * 1.6, 0.01, 4, 12), M.glow);
    ring.position.z = len - 0.04;
    g.add(ring);
    const lens = hexCrystal(r * 1.1, len * 0.18, r * 1.2, M.crystal);
    lens.rotation.x = PI / 2;
    lens.position.z = len * 0.5;
    g.add(lens);
    return g;
}
const _light = (b, y, z) => { const L = new T.PointLight(0xffffff, 0.15, 3.5, 2); L.color.set(EL.color); L.position.set(0, y, z); b.add(L); LIGHTS.push(L); };
