function drawCard(g, x, y, w, h, rot, c, o) {
    o = o || {};
    g.save();
    g.translate(x, y);
    g.rotate(rot);
    if (o.lift) {
        g.shadowColor = 'rgba(255,255,255,0.9)';
        g.shadowBlur = 34;
    }
    else {
        g.shadowColor = 'rgba(0,0,0,0.5)';
        g.shadowBlur = 16;
        g.shadowOffsetY = 6;
    }
    rrect(g, -w / 2, -h / 2, w, h, 16);
    g.fillStyle = '#fbf6ea';
    g.fill();
    g.shadowColor = 'transparent';
    rrect(g, -w / 2 + 8, -h / 2 + 8, w - 16, h - 16, 10);
    g.fillStyle = c.col;
    g.fill();
    rrect(g, -w / 2 + 16, -h / 2 + 44, w - 32, h * 0.46, 8);
    g.fillStyle = c.art || '#17323d';
    g.fill();
    if (c.img) {
        g.save();
        rrect(g, -w / 2 + 16, -h / 2 + 44, w - 32, h * 0.46, 8);
        g.clip();
        const s = h * 0.5;
        g.drawImage(c.img, -s / 2, -h / 2 + 44 + (h * 0.46 - s) / 2, s, s);
        g.restore();
    }
    text(g, c.name, 0, -h / 2 + 34, { font: font('bang', c.name.length > 11 ? 21 : 25), fill: '#16212a', align: 'center' });
    rrect(g, -w / 2 + 16, -h / 2 + 52 + h * 0.46, w - 32, h - h * 0.46 - 70, 8);
    g.fillStyle = '#fbf6ea';
    g.fill();
    text(g, c.who, 0, -h / 2 + 76 + h * 0.46, { font: font('ui', 13), fill: '#5a6a74', align: 'center' });
    (c.rule || []).forEach((line, i) => text(g, line, 0, -h / 2 + 100 + h * 0.46 + i * 19, { font: font('ui', 14), fill: '#16212a', align: 'center' }));
    g.beginPath();
    g.arc(-w / 2 + 6, -h / 2 + 6, 24, 0, 7);
    g.fillStyle = '#16212a';
    g.fill();
    gem2d(g, -w / 2 + 6, -h / 2 + 6, 15, '#3aa0ff');
    text(g, String(c.cost), -w / 2 + 6, -h / 2 + 14, { font: font('title', 21), fill: '#ffffff', align: 'center', stroke: '#16212a', sw: 5 });
    g.restore();
}
