        const loop = yy => { const pts = r.poly.map(p => new T.Vector3(p[0], yy, p[1])); pts.push(pts[0].clone()); return new T.Line(new T.BufferGeometry().setFromPoints(pts), line(hex, home ? 0.95 : 0.6)); };
